<?php namespace App\Filament\Pages;use Filament\Pages\Page;use Illuminate\Support\Facades\DB;
class UpbringingDashboard extends Page{protected static ?string $navigationIcon='heroicon-o-heart';protected static ?string $navigationLabel='Обзор отдела';protected static ?string $navigationGroup='Воспитательная работа';protected static ?int $navigationSort=1;protected static string $view='filament.pages.upbringing-dashboard';public array $stats=[],$months=[],$directions=[],$groups=[],$overdue=[];
public function mount():void{$p=request()->attributes->get('academic_period');if(!$p)return;$pid=$p->id;$q=fn($t)=>DB::table($t)->where('academic_period_id',$pid);$this->stats=['planned'=>$q('upbringing_events')->where('status','planned')->count(),'done'=>$q('upbringing_events')->whereIn('status',['done','completed'])->count(),'cases'=>$q('student_support_cases')->where('status','!=','closed')->count(),'tasks'=>$q('upbringing_tasks')->whereNotIn('status',['done','cancelled'])->count(),'achievements'=>$q('student_achievements')->count(),'appeals'=>$q('upbringing_appeals')->where('status','new')->count(),'overdue_cases'=>$q('student_support_cases')->where('status','!=','closed')->whereNotNull('next_contact_on')->where('next_contact_on','<',today())->count(),'overdue_tasks'=>$q('upbringing_tasks')->whereNotIn('status',['done','cancelled'])->whereNotNull('due_on')->where('due_on','<',today())->count()];
$this->months=$q('upbringing_events')->whereNotNull('starts_at')->selectRaw("DATE_FORMAT(starts_at,'%Y-%m') ym,COUNT(*) total")->groupBy('ym')->orderBy('ym')->get()->map(fn($x)=>(array)$x)->all();
$this->directions=$q('upbringing_events')->select('direction',DB::raw('COUNT(*) total'))->groupBy('direction')->orderByDesc('total')->limit(8)->get()->map(fn($x)=>(array)$x)->all();
$students=DB::table('students as s')->leftJoin('study_groups as g','g.id','=','s.current_group_id')->leftJoin('student_merit_actions as a',function($j)use($pid){$j->on('a.student_id','=','s.id')->where('a.academic_period_id',$pid)->where('a.status','active');})->where('s.status','active')->groupBy('s.id','g.name')->select('s.id','g.name as group_name',DB::raw('COALESCE(SUM(a.rating_points),0) rating'))->get();$this->groups=$students->groupBy('group_name')->map(fn($x)=>['name'=>$x->first()->group_name?:'Без группы','students'=>$x->count(),'rating'=>$x->sum('rating')])->sortByDesc('rating')->take(6)->values()->all();
$this->overdue=$q('student_support_cases')->where('status','!=','closed')->whereNotNull('next_contact_on')->where('next_contact_on','<',today())->orderBy('next_contact_on')->limit(5)->get(['id','student_id','reason','next_contact_on'])->map(function($x){$s=DB::table('students')->where('id',$x->student_id)->first();return['id'=>$x->id,'student'=>$s?trim($s->last_name.' '.$s->first_name):'Студент #'.$x->student_id,'reason'=>$x->reason,'date'=>$x->next_contact_on];})->all();}
public static function canAccess():bool{$u=auth()->user();return $u&&($u->isSuperAdmin()||$u->hasRole('admin')||$u->canDo('upbringing.view'));}}
